pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        // Use a helper that always returns true on transferFrom calls to simulate success
        // Address of the helper is what we pass as contract_address
