pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
        }
        SuccessfulCallee callee = new SuccessfulCallee();
        bool ok;
        try c.transfer(address(callee), tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            // revert case is not in scope; the property only concerns non-reverting calls.
            ok = true; // trivially satisfy the assertion when it reverts
        }
        assertTrue(ok);
    }
}

contract SuccessfulCallee {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    fallback() external payable { }
    receive() external payable { }
}

