pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        for(uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
            vm.assume(tos[i] != address(c));
        }
        MockToken token = new MockToken();
        address tokenAddr = address(token);
        vm.assume(contract_address == tokenAddr);
        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool result) {
            ok = true;
            assertTrue(result == true);
        } catch {
            ok = false;
        }
        if(ok) {
            assertTrue(true);
        }
    }
}

contract MockToken {
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        return true;
    }
}
